StructuralRule.Script:
var isJsf2 = loadPersistedObject("program.isJsf2");

if (isJsf2) {
    rule.Predicate = String("FunctionCall: function.name == \"FORTIFY_NON_EXISTENT\"");
}

StructuralRule.Predicate:
Comment: html and text matches ".*" and
                  /* added an exception for server-side includes -- bug 34067 */
                  not text matches ".*#config.*|.*#echo.*|.*#elif.*|.*#else.*|.*#endif.*|.*#exec.*|.*#flastmod.*|.*#fsize.*|.*#if.*|.*#include.*|.*#printenv.*|.*#set.*" and
                  /* added an exception for conditional comments that work in IE -- bug 35756 */
                  not text matches ".*\[if(\s)+(gt|gte|lt|lte|!)?(\s)*IE.*|.*<!\[endif\].*"

