AssignmentStatement: lhs.location is
                [FieldAccess: instance.location is [VariableAccess: this] and field is [Field dec: not dec.name startsWith "_jspx"]*] and
        enclosingClass.supers contains [Class: name == "javax.servlet.Servlet"] and
        not enclosingClass.supers contains [Class: name == "javax.servlet.SingleThreadModel"] and
        not enclosingFunction is
                /* EXCEPTION: enclosing function is a constructor or its name starts with "init" */
                [constructor or name matches "init.*" or
                /* EXCEPTION: enclosing function takes ServletConfig as one of its parameters */
                 (parameterTypes.length > 0 and parameterTypes contains [name == "javax.servlet.ServletConfig"]) or
                /* EXCEPTION: enclosing function is only reachable from a constructor */
                (not public and (callers.length == 0 or callers contains [constructor]) and not callers contains [not constructor]) or
                /* EXCEPTION: enclosing function starts with "set" and is not reachable from any of the non-constructor functions */
                (name matches "set.*" and not callers contains [not constructor]) or
                /* EXCEPTION: callers of enclosing function do not contain any functions other than init() */
                (callers.length != 0 and not callers contains [Function: not name matches "init.*"])]

AssignmentStatement: lhs.location is
                [FieldAccess: instance.location is [VariableAccess: this] and field is [Field dec: not dec.name startsWith "_jspx"]*] and
        enclosingClass.supers contains [Class: name == "javax.servlet.Servlet"] and
        not enclosingClass.supers contains [Class: name == "javax.servlet.SingleThreadModel"] and
        not enclosingFunction is
                /* EXCEPTION: enclosing function is a constructor or its name starts with "init" */
                [constructor or name matches "init.*" or name == "jspInit" or
                /* EXCEPTION: enclosing function takes ServletConfig as one of its parameters */
                 (parameterTypes.length > 0 and parameterTypes contains [name == "javax.servlet.ServletConfig"]) or
                /* EXCEPTION: enclosing function is only reachable from a constructor */
                (not public and (callers.length == 0 or callers contains [constructor]) and not callers contains [not constructor]) or
                /* EXCEPTION: enclosing function starts with "set" and is not reachable from any of the non-constructor functions */
                (name matches "set.*" and not callers contains [not constructor]) or
                /* EXCEPTION: callers of enclosing function do not contain any functions other than init() */
                (callers.length != 0 and not callers contains [Function: not name matches "init.*"])]

