CharacterizationRule.StructuralMatch:
FunctionCall fc: function.name matches "_jspService|execute"
        and function.enclosingClass.name matches "http://(www\.)?springframework\.org/tags/(message|theme)"
        and namedParameters contains [
                NamedParameter: name matches "jspContext|context" and
                expression is [Expression context: ]
        ]
        and (
            /* any of the escapers is set and the other one is not present (defaults to false)*/
            (namedParameters contains [
                NamedParameter: name is "htmlEscape" and expression.constantValue == "true"
            ] and not namedParameters contains [
                NamedParameter: name is "javaScriptEscape"
            ]) or (not namedParameters contains [
                NamedParameter: name is "htmlEscape"
            ] and namedParameters contains [
                NamedParameter: name is "javaScriptEscape" and expression.constantValue == "true"
            ])
            /* any of the escapers is missing (default to false), but not both of them */
            or (namedParameters contains [
                NamedParameter: name is "htmlEscape"
            ] and not namedParameters contains [
                NamedParameter: name is "javaScriptEscape"
            ]) or (not namedParameters contains [
                NamedParameter: name is "htmlEscape"
            ] and not namedParameters contains [
                NamedParameter: name is "javaScriptEscape"
            ])
        )
        and not namedParameters contains [NamedParameter: name ==  "var"]
        and namedParameters contains [
                NamedParameter: name matches "jspBody|body" and
                expression is [Expression body: ]
        ]
        and namedParameters contains [
                NamedParameter a: name matches "text|arguments|message|argumentSeparator"
                and expression is [Expression attr: ]
        ]

